$$('[data-trigger]').forEach(button=>{const panel=document.getElementById(button.getAttribute('aria-controls'));if(!panel)return;function toggle(open){button.setAttribute('aria-expanded',String(open));panel.hidden=false;panel.style.setProperty('grid-template-rows',open?'1fr':'0fr','important');}toggle(button.getAttribute('aria-expanded')==='true');button.addEventListener('click',()=>toggle(button.getAttribute('aria-expanded')!=='true'));});
const slides=$$('[data-gallery-slide]');const slideParent=slides[0]?.parentElement;let index=0;
