const viewport=$('buybox-gallery .embla__container')?.parentElement;let touchX=0,touchY=0;viewport?.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;touchY=e.changedTouches[0].clientY;},{passive:true});viewport?.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX,dy=e.changedTouches[0].clientY-touchY;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))slide(index+(dx<0?1:-1));},{passive:true});
const modal=$('[data-nutrition-modal]');let modalOpener=null;function nutrition(open){if(!modal)return;modal.hidden=!open;if(open&&!modal.open){modalOpener=document.activeElement;modal.showModal();}if(!open&&modal.open){modal.close();modalOpener?.focus();}modal.setAttribute('aria-hidden',String(!open));if(open)$('[data-nutrition-close]',modal)?.focus();}
$$('[data-nutrition-open]').forEach(b=>b.addEventListener('click',()=>nutrition(true)));$$('[data-nutrition-close]').forEach(b=>b.addEventListener('click',()=>nutrition(false)));modal?.addEventListener('cancel',e=>{e.preventDefault();nutrition(false);});nutrition(false);
